// Observation assembler: the byte-exact on-board twin of walker_env._obs().
//
// The layout, joint count and command width all come from obs_spec.h, which is
// GENERATED by tools/gen_obs_spec.py from the deployed run's config + MJCF --
// never hand-edited. The same generator freezes real _obs() outputs
// into host/vectors/obs_vectors.h, so a layout drift is a red test rather than
// a robot that walks into a wall.
//
// The frame (the deployed spec: 12 joints, 7 command channels):
//   [ q(12) | dq(12) | up(3) | linvel(3) | gyro(3) | prev_action(12)
//     | height(1) | sin,cos(2) | cmd(7) ]  = 55 floats
// and the policy sees kHistLen of those, newest first: obs = [f_t, f_t-1, f_t-2].
//
// linvel and height are ZERO on hardware: the training config sets imu_obs=1
// because the robot has no sensor for torso linear velocity or height. The
// generator asserts that, so this cannot silently become wrong.
#pragma once
#include <stddef.h>
#include <stdint.h>

#include "obs/obs_spec.h"

namespace obs {

// Everything the control loop must supply per tick.
struct Inputs {
    float q[kNumJoints];             // joint angles, rad, sim sign convention
    float dq[kNumJoints];            // joint velocities, rad/s
    float up[3];                     // torso up-vector, body frame (from IMU)
    float gyro[3];                   // torso angular velocity, rad/s
    float prev_action[kActDim];      // last action, [-1, 1]
    float phase;                     // gait-clock phase, rad
    float cmd[kNumCmd];              // command channels
};

// Write one kFrameDim-wide observation frame.
void assembleFrame(const Inputs& in, float* out);

// The kHistLen-deep frame ring. Semantics copied from walker_env: the obs
// handed to the policy at tick t is [f_t, f_{t-1}, ..., f_{t-H+1}], and the
// history is updated AFTER the policy has been fed.
class History {
  public:
    // Reset: every history slot becomes `frame` (walker_env does the same on
    // env.reset(), so the first tick is not fed a ring of zeros).
    void fill(const float* frame);
    // Build the full observation from the current frame plus the ring.
    void build(const float* frame, float* obs) const;
    // Push the frame that was just used; drops the oldest.
    void push(const float* frame);

  private:
    // kHistLen - 1 previous frames, newest first.
    float prev_[(kHistLen > 1 ? kHistLen - 1 : 1)][kFrameDim] = {};
};

// The gait clock walker_env advances on-board:
//   phase = wrap_pi(phase + 2*pi*dt*freq)
// Training draws the frequency per episode from the run's gait_freq_range; the
// robot runs its midpoint, kGaitFreqHz (generated into obs_spec.h per policy).
class GaitClock {
  public:
    explicit GaitClock(float hz = kGaitFreqHz) : freq_(hz) {}
    void advance(float dt);
    // Speed clock (kSpeedClock): the phase advances at freq * scale where
    // scale = clip(sqrt(v_planar / kSpeedClockRef), kSpeedClockLo,
    // kSpeedClockHi) and v_planar = hypot(cmd vx, cmd vy) -- the mirror of
    // env_mjx.speed_clock_scale / walker_env. With kSpeedClock false this
    // is advance(dt).
    void advanceSpeedClock(float dt, float v_planar);
    static float speedScale(float v_planar);
    void setFrequency(float hz) { freq_ = hz; }
    float phase() const { return phase_; }
    void setPhase(float p) { phase_ = p; }
    // Coast: advance(dt) as usual until the phase reaches `target` (moving
    // forward only), then hold exactly there. Stateless -- once the phase IS
    // the (wrapped) target it stays; any advance() moves it off again.
    // Returns true while held at the target.
    bool coastTo(float dt, float target);

  private:
    float phase_ = 0.0f;
    float freq_;
};

// What the clock does at a PLAIN STAND for a policy trained with it running
// (kClockStandFreeze false) -- a firmware option, CLI `standclock`, default
// kRun (the as-trained behaviour). The 2026-11-02 policy stand: the phase
// kept running at 1.5 Hz at the stand command and every joint goal jittered
// 0.1-0.5 deg rms at exactly 1.5 and 3 Hz (experiments/policy/stand-still).
//   kRun     advance as trained
//   kFreeze  hold the phase where the stand began
//   kCoast   keep the trained rate until the phase reaches the stand phase,
//            then hold there: the policy never sees the clock jump or slow,
//            and the stand always settles at the same (chosen) phase
// A policy trained with the clock frozen (kClockStandFreeze) always holds.
enum class StandClock : uint8_t { kRun = 0, kFreeze = 1, kCoast = 2 };

// Training's plain-stand gate (env_mjx plain_stand): no locomotion command
// and no lift. cmd: kNumCmd wide, AFTER policy::pinFrozen.
bool plainStand(const float* cmd);

// One control tick of the gait clock: the speed clock under a locomotion
// command, the StandClock rule at a plain stand. THE clock rule -- ctrl_task
// and the SIL harness both call it, so the two cannot drift apart.
void tickGaitClock(GaitClock& clk, const float* cmd, StandClock mode,
                   float stand_phase);

}  // namespace obs
